{
  "results": [
    {
      "criterion_id": "criterion-1",
      "passed": true,
      "evidence": [
        "final_message 列出订单服务、消息队列、支付适配器和外部支付商的已知链路，并指出异步消息边界与外部依赖边界。",
        "final_message 将回调入口、状态机、结果回传路径等列为待核验信息，明确不将其当作既有事实。"
      ],
      "failures": []
    },
    {
      "criterion_id": "criterion-2",
      "passed": true,
      "evidence": [
        "final_message 为消息消费、支付客户端、回调和结果落库提出测试接缝与替身，并区分替身测试和真实队列验证。",
        "final_message 覆盖隔离主题与消费者组、定向故障注入、固定种子和触发点、关联记录，以及版本配置和种子数据的环境复现。"
      ],
      "failures": []
    },
    {
      "criterion_id": "criterion-3",
      "passed": false,
      "evidence": [
        "final_message 将故障注入限定于测试部署，提出隔离主题、消费者组和沙箱商户，并声明不涉及生产写入。",
        "final_message 要求验证非法签名回调不会更新状态，且复现包不得包含密钥。"
      ],
      "failures": [
        "未明确限定测试账号、服务凭据和故障注入入口的最小权限。",
        "未明确验证租户授权与租户间数据隔离；run_id 和测试资源隔离不能替代该检查。"
      ]
    },
    {
      "criterion_id": "criterion-4",
      "passed": true,
      "evidence": [
        "final_message 按 P0、P1、P2 标出改进优先级和相对成本，并将支付重复受理、异步恢复和积压等风险对应到改进项。",
        "final_message 的场景表逐项给出触发方式、建议断言和必须保存的证据，包括幂等键、受理记录、重投记录及状态转换。"
      ],
      "failures": []
    },
    {
      "criterion_id": "criterion-5",
      "passed": true,
      "evidence": [
        "final_message 明确本次未执行系统测试，模拟器能力和协议真实性仍需核验，不能据此宣布方案有效。",
        "final_message 要求预先约定重复次数、最长等待时间和恢复目标，并列出业务及支付负责人需要决定的状态转换、补偿和幂等规则。",
        "final_message 指出替身与真实支付商、沙箱与生产环境及容量差异带来的残余风险。"
      ],
      "failures": []
    }
  ]
}
